//! 📐️ Typed uninitialized array storage admits each scalar and field store without any N-element callback at birth or publication.
use super::*;
use std::mem::MaybeUninit;
pub struct ArrayReceiving<T:OwnedScalar+Copy,const N:usize>{source:OwnedSlot<FieldValue>,current:OwnedSlot<FieldValue>,output:OwnedSlot<[T;N]>,rows:ManuallyDrop<MaybeUninit<[T;N]>>,pending:Option<T>,live:usize,index:usize,phase:u8,closing:bool,failed:bool}
impl<T:OwnedScalar+Copy,const N:usize>Default for ArrayReceiving<T,N>{fn default()->Self{Self{source:Default::default(),current:Default::default(),output:Default::default(),rows:ManuallyDrop::new(MaybeUninit::uninit()),pending:None,live:0,index:0,phase:0,closing:false,failed:false}}}
impl<T:OwnedScalar+Copy,const N:usize>DslOwnedReceivingField for[T;N]{type Cursor=ArrayReceiving<T,N>;fn receiving_cursor()->Self::Cursor{Self::Cursor::default()}}
impl<T:OwnedScalar+Copy,const N:usize>OwnedFieldReceiving<[T;N]>for ArrayReceiving<T,N>{
 fn demands(&self,_:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.failed{return Err(invariant())}match self.phase{2=>Ok(RetirementDemand{copy_bytes:T::creation_bytes(),depth:1,..Default::default()}),3=>Ok(payload::<T>()),5 if !self.source.terminal_is_empty()=>self.source.close_demands(body),6=>Ok(Default::default()),_=>Ok(metadata::<()>())}}
 fn step(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{if self.closing||self.failed{return RetainedWorkOutcome{result:Err(invariant().into()),work:0}}if self.phase==6{return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.demands(source,body){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if self.phase==5&&!self.source.terminal_is_empty(){let turn=close_source(&mut self.source,native,g);if turn.result.is_err()&&turn.work>0{self.failed=true}return turn}if let Err(e)=native.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}let result=(||{match self.phase{0=>{if !matches!(source.as_ref(),Some(FieldValue::Tuple(v))if v.len()==N){return Err(invalid())}*self.source.value=source.take();self.phase=1;},1=>{if self.index==N{self.phase=4;}else{let Some(FieldValue::Tuple(v))=self.source.value.as_mut()else{return Err(invariant())};if !self.current.terminal_is_empty(){return Err(invariant())}*self.current.value=Some(std::mem::replace(v.get_mut(self.index).ok_or_else(invariant)?,FieldValue::Absent));self.phase=2;}},2=>{self.pending=Some(T::take_source(&mut self.current.value)?);self.phase=3;},3=>{if self.index!=self.live||self.live>=N{return Err(invariant())}let value=self.pending.take().ok_or_else(invariant)?;unsafe{self.rows.as_mut_ptr().cast::<T>().add(self.live).write(value)}self.live+=1;self.index+=1;self.phase=1;},4=>{if self.live!=N{return Err(invariant())}*self.output.value=Some(unsafe{self.rows.as_ptr().read()});self.live=0;self.phase=5;},5=>self.phase=6,_=>return Err(invariant())}Ok(receipt(d))})();if result.is_err(){self.failed=true}RetainedWorkOutcome{result:result.map_err(|e|OriginalReceivingPrimary::from(e.with_retained_progress(receipt(metadata::<()>())))),work:1}}
 fn is_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==6&&self.output.value.is_some()}
 fn take_into(&mut self,output:&mut Option<[T;N]>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if !self.is_ready(){return RetainedWorkOutcome{result:Err(invariant()),work:0}}move_into(&mut self.output.value,output,g)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if self.pending.is_some()||self.live>0{return Ok(metadata::<()>())}if !self.output.terminal_is_empty(){return self.output.close_demands(body)}self.source.close_demands(body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if !self.closing{self.closing=true;return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if !self.current.terminal_is_empty(){return self.current.close_step(g)}if self.pending.is_some(){self.pending=None;return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if self.live>0{self.live-=1;return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if !self.output.terminal_is_empty(){return self.output.close_step(g)}self.source.close_step(g)}
 fn terminal_is_empty(&self)->bool{self.current.terminal_is_empty()&&self.pending.is_none()&&self.live==0&&self.output.terminal_is_empty()&&self.source.terminal_is_empty()}
}
impl<T:OwnedScalar+Copy,const N:usize>Drop for ArrayReceiving<T,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"owned fixed array requires paid terminal closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.rows)}}}}
